INSERT INTO reviews (id, evidence_id, store, app_id, source_record_id, canonical_url, collection_run_id, collection_method, source_permission_id, review_title, review_text, language_original, language_detected, translated_text, content_hash, content_status, redaction_status, storefront, app_version, star_rating, review_created_at, review_updated_at, retrieved_at, provider_name, store_listing_url, eligibility_status, source_policy_version, retention_expiry_at, deletion_status, created_at, review_text_original, app_name, package_name, language_confidence, script_detected, language_detection_method, redaction_categories, pii_processed_at, developer_reply_present, provider_limit_snapshot, sip_relevance_status, matched_query_categories, matched_terms, relevance_rule_version, mentions_sip, mentions_mutual_fund, mentions_payment, mentions_mandate, mentions_autopay, mentions_instalment, mentions_nav, mentions_returns, mentions_units, mentions_pause_stop, mentions_restart, mentions_redemption, mentions_support, mentions_kyc, mentions_trust, dedupe_group_id, duplicate_status, duplicate_of_evidence_id, deduplication_method, data_quality_score, data_quality_status, data_quality_issues, ai_enrichment_status, ai_lifecycle_stage, ai_primary_pain_point, ai_pain_points, ai_confidence_score, ai_confidence_tier, ai_adjudication_status) VALUES (548, 'EV_ZERO_APP_fcdec754', 'apple_app_store', 'zerodha_coin', '12269930485', 'https://itunes.apple.com/in/review?id=1392892554&type=Purple%20Software', 'RUN_ZERO_APP_8F827050', 'apple_app_store_rss', 'PHASE2-AUDIT-APPLE-RSS-001', 'Arrogant people, don’t take feedback', 'While all their peers have merged mutual funds with their main app, zerodha wont because they don’t want a super app! This app is so basic and so limited features: - no option for creating daily SIP - no option to sort on XIRR - no option to model gains or STCG/LTCG! - customers don’t mean anything to them as they are discount brokers!! - Give any suggestion to them and they are like “we are the largest broker, so take what you get and shut up!” - Separate app for mutual funds, no other broker does that! If you ask why, their answer is same as above! - Unjustified charges! Delivery trades are free but they charge for buy back orders, which are delivery orders! Similarly if you apply for a buy offer of a company, they charge even if the order is not accepted! If you ask why, the answer is again same as above! - The DP charge is 300/- per annum, and they say that it’s to be charged quarterly like any other broker! But they charge it every 90 days, in their calculations 90 days * 4 = 1 year! Don’t ask why, you will get the same answer as above!
