INSERT INTO reviews (id, evidence_id, store, app_id, source_record_id, canonical_url, collection_run_id, collection_method, source_permission_id, review_title, review_text, language_original, language_detected, translated_text, content_hash, content_status, redaction_status, storefront, app_version, star_rating, review_created_at, review_updated_at, retrieved_at, provider_name, store_listing_url, eligibility_status, source_policy_version, retention_expiry_at, deletion_status, created_at, review_text_original, app_name, package_name, language_confidence, script_detected, language_detection_method, redaction_categories, pii_processed_at, developer_reply_present, provider_limit_snapshot, sip_relevance_status, matched_query_categories, matched_terms, relevance_rule_version, mentions_sip, mentions_mutual_fund, mentions_payment, mentions_mandate, mentions_autopay, mentions_instalment, mentions_nav, mentions_returns, mentions_units, mentions_pause_stop, mentions_restart, mentions_redemption, mentions_support, mentions_kyc, mentions_trust, dedupe_group_id, duplicate_status, duplicate_of_evidence_id, deduplication_method, data_quality_score, data_quality_status, data_quality_issues, ai_enrichment_status, ai_lifecycle_stage, ai_primary_pain_point, ai_pain_points, ai_confidence_score, ai_confidence_tier, ai_adjudication_status) VALUES (1147, 'EV_ZERO_APP_1307f5b9', 'apple_app_store', 'zerodha_kite', '13884242430', 'https://itunes.apple.com/in/review?id=1449453802&type=Purple%20Software', 'RUN_ZERO_APP_D0D5D793', 'apple_app_store_rss', 'PHASE2-AUDIT-APPLE-RSS-001', 'Just too basic', 'I only use this app because I trade a lot and paying AMC on zerodha comes out to be lower overall per year than paying per trade on groww. But god, this app is so frustrating. The UI is not user friendly at all, and everything leads to a redirect to browser. Basic information isn’t displayed in orderly fashion, and basic features like history of cancelled orders are missing. If you have been using groww, using zerodha is like downgrading from an Audi to a kia. The QoL and the whole ecosystem is just worlds apart. The day groww implements an AmC option for frequent traders is the day I will dump zerodha. Even now I only use zerodha to book the trade, all the actual R&D is done on groww before hand and all my MF are on groww too. This company is so pretentious with all its “honest” marketing, maybe they need the same energy to actually listen to their customers and implement features instead of pandering to people on social media on pseudo morality.', 'unknown', 'en', NULL, '1307f5b9bd8dbd203d6055e1139c9a80e683ad13ec0c45f34548a2e88edbff5e', 'NORMALIZED', 'CLEAN', 'IN', '3.11.3', 1, '2026-03-25 04:31:37', NULL, '2026-11-06 16:11:48', NULL, NULL, 'ELIGIBLE', '1.0.0', '2027-11-06 16:11:48', 'ACTIVE', '2026-11-06 16:11:48', 'I only use this app because I trade a lot and paying AMC on zerodha comes out to be lower overall per year than paying per trade on groww. But god, this app is so frustrating. The UI is not user friendly at all, and everything leads to a redirect to browser. Basic information isn’t displayed in orderly fashion, and basic features like history of cancelled orders are missing. If you have been using groww, using zerodha is like downgrading from an Audi to a kia. The QoL and the whole ecosystem is just worlds apart. The day groww implements an AmC option for frequent traders is the day I will dump zerodha. Even now I only use zerodha to book the trade, all the actual R&D is done on groww before hand and all my MF are on groww too. This company is so pretentious with all its “honest” marketing, maybe they need the same energy to actually listen to their customers and implement features instead of pandering to people on social media on pseudo morality.', 'Zerodha Kite - Trade & Invest', 'com.zerodha.kite3', 0.85, 'LATIN', 'heuristic_lexical_script_v1', '[]', '2026-11-06 16:53:00', 0, NULL, 'GENERAL_INVESTMENT_RELEVANT', '[]', '[]', '1.0.0', 0, 1, 0,