INSERT INTO opportunities (opportunity_id, priority_rank, title, theme_code, lifecycle_stage, target_application, opportunity_score, prevalence_score, severity_score, lifecycle_criticality, actionability_score, evidence_confidence, problem_statement, proposed_intervention, testable_hypothesis, exemplar_verbatim_quote, lifecycle_status, primary_metric, guardrail_metric, created_at, updated_at) VALUES ('OPP-06', 1, 'Beginner Return Reality Context & Market Volatility Reassurance', 'RETURN_DISPLAY_CONFUSION', 'S3_HABIT', 'Groww & INDmoney', 6.39, 7.25, 7.5, 6.5, 9.0, 0.864, 'First-time investors panic when their portfolio shows short-term negative returns within months 1-3, unaware that equity mutual funds fluctuate daily.', '1. ''Why Rupee-Cost Averaging Works'' visual explainer during market dips.
INSERT INTO opportunities (opportunity_id, priority_rank, title, theme_code, lifecycle_stage, target_application, opportunity_score, prevalence_score, severity_score, lifecycle_criticality, actionability_score, evidence_confidence, problem_statement, proposed_intervention, testable_hypothesis, exemplar_verbatim_quote, lifecycle_status, primary_metric, guardrail_metric, created_at, updated_at) VALUES ('OPP-01', 2, 'Proactive Mandate Status Tracker & Instant UPI Autopay Fallback', 'MANDATE_REGISTRATION_FAILURE', 'S1_SETUP', 'Groww & Peers', 6.38, 2.0, 9.5, 10.0, 9.0, 0.874, 'First-time investors encounter opaque bank mandate delays and e-mandate rejections, resulting in abandonment before the first instalment.', '1. Live visual mandate stepper showing bank/NPCI verification stages.
INSERT INTO opportunities (opportunity_id, priority_rank, title, theme_code, lifecycle_stage, target_application, opportunity_score, prevalence_score, severity_score, lifecycle_criticality, actionability_score, evidence_confidence, problem_statement, proposed_intervention, testable_hypothesis, exemplar_verbatim_quote, lifecycle_status, primary_metric, guardrail_metric, created_at, updated_at) VALUES ('OPP-04', 3, 'Zero-Surprise Mandate Cancellation & Debit Termination Guarantee', 'SIP_CANCELLATION_DIFFICULTY', 'S6_PAUSE_STOP', 'Groww & Paytm Money', 5.75, 2.0, 9.0, 8.0, 8.5, 0.874, 'Investors who cancel an active SIP experience continued autopay deductions due to NPCI mandate de-registration latency, causing severe trust destruction.', '1. Instant de-linking of autopay mandate with bank confirmation SMS within 2 hours.
INSERT INTO opportunities (opportunity_id, priority_rank, title, theme_code, lifecycle_stage, target_application, opportunity_score, prevalence_score, severity_score, lifecycle_criticality, actionability_score, evidence_confidence, problem_statement, proposed_intervention, testable_hypothesis, exemplar_verbatim_quote, lifecycle_status, primary_metric, guardrail_metric, created_at, updated_at) VALUES ('OPP-07', 4, 'Priority Financial Transaction Support Escalation Pathway', 'CUSTOMER_SUPPORT_DELAY', 'S5_FRICTION', 'Groww & Angel One', 5.54, 2.0, 9.0, 8.5, 8.0, 0.836, 'Investors facing critical money deductions are trapped in automated AI bot loops with no human contact, turning solvable operational bugs into 1-star rage reviews.', '1. Smart triage: Any ticket containing ''money deducted'' or ''mandate fail'' bypasses bot directly to Tier-2 human agent.
INSERT INTO opportunities (opportunity_id, priority_rank, title, theme_code, lifecycle_stage, target_application, opportunity_score, prevalence_score, severity_score, lifecycle_criticality, actionability_score, evidence_confidence, problem_statement, proposed_intervention, testable_hypothesis, exemplar_verbatim_quote, lifecycle_status, primary_metric, guardrail_metric, created_at, updated_at) VALUES ('OPP-02', 5, 'Transparent T+2 NAV & Unit Allotment Lifecycle Visualizer', 'INVESTMENT_NOT_REFLECTED', 'S2_EARLY', 'Groww (Primary)', 5.5, 2.0, 9.8, 9.5, 9.5, 0.75, 'Money is deducted from the investor''s bank account, but units are not allotted until T+2, leading beginner investors to fear their funds are lost or stolen.', '1. ''Money Safe & In-Transit'' status card immediately upon bank debit.
INSERT INTO opportunities (opportunity_id, priority_rank, title, theme_code, lifecycle_stage, target_application, opportunity_score, prevalence_score, severity_score, lifecycle_criticality, actionability_score, evidence_confidence, problem_statement, proposed_intervention, testable_hypothesis, exemplar_verbatim_quote, lifecycle_status, primary_metric, guardrail_metric, created_at, updated_at) VALUES ('OPP-05', 6, 'Automated Smart Autopay Recovery on Insufficient Balance', 'MISSED_INSTALMENT', 'S5_FRICTION', 'Groww & Peers', 4.91, 2.0, 8.5, 8.5, 8.5, 0.75, 'Monthly instalment fails on salary delay, triggering bank bounce charges and silent SIP stoppage without user realization.', '1. Balance check warning 24h prior to SIP due date.
INSERT INTO opportunities (opportunity_id, priority_rank, title, theme_code, lifecycle_stage, target_application, opportunity_score, prevalence_score, severity_score, lifecycle_criticality, actionability_score, evidence_confidence, problem_statement, proposed_intervention, testable_hypothesis, exemplar_verbatim_quote, lifecycle_status, primary_metric, guardrail_metric, created_at, updated_at) VALUES ('OPP-03', 7, 'Frictionless 1-Click SIP Pause & Flexible Skip Mechanism', 'SIP_PAUSE_DIFFICULTY', 'S5_FRICTION', 'Groww & Zerodha Coin', 4.86, 2.0, 8.0, 8.5, 9.0, 0.75, 'Investors facing temporary cash crunches cannot easily pause or skip an instalment, forcing them into mandate bounce penalties or full SIP cancellation.', '1. 1-click ''Skip this Month'' toggle directly on upcoming instalment cards.
